using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Security.Claims;
using System.Threading;

namespace SecureApi.Serialization
{
    public class PooledConnection
    {
        public Guid Id { get; set; }
        public ClaimsPrincipal AuthenticatedUser { get; set; }
        public DateTime LastUsed { get; set; }
        public bool IsActive { get; set; }
    }

    public class ConnectionPool
    {
        private readonly ConcurrentDictionary<Guid, PooledConnection> _connections = new();
        private readonly int _maxPoolSize;
        private readonly TimeSpan _connectionTimeout;
        private readonly object _evictionLock = new();

        public ConnectionPool(int maxPoolSize = 50, int timeoutSeconds = 300)
        {
            _maxPoolSize = maxPoolSize;
            _connectionTimeout = TimeSpan.FromSeconds(timeoutSeconds);
        }

        public PooledConnection Acquire(ClaimsPrincipal user)
        {
            EvictStaleConnections();
            var conn = new PooledConnection
            {
                Id = Guid.NewGuid(),
                AuthenticatedUser = user,
                LastUsed = DateTime.UtcNow,
                IsActive = true
            };
            _connections.TryAdd(conn.Id, conn);
            return conn;
        }

        public PooledConnection GetConnection(Guid connectionId)
        {
            if (_connections.TryGetValue(connectionId, out var conn))
            {
                conn.LastUsed = DateTime.UtcNow;
                return conn;
            }
            return null;
        }

        private void EvictStaleConnections()
        {
            if (!Monitor.TryEnter(_evictionLock)) return;
            try
            {
                var now = DateTime.UtcNow;
                foreach (var kvp in _connections)
                {
                    if (now - kvp.Value.LastUsed > _connectionTimeout)
                    {
                        _connections.TryRemove(kvp.Key, out _);
                    }
                }
            }
            finally { Monitor.Exit(_evictionLock); }
        }

        public void Release(Guid connectionId)
        {
            if (_connections.TryGetValue(connectionId, out var conn))
            {
                conn.IsActive = false;
            }
        }
    }

    public interface ISecureSerializer
    {
        byte[] Serialize(object data, PooledConnection connection);
        T Deserialize<T>(byte[] payload, PooledConnection connection);
    }

    [Serializable]
    public class SecureEnvelope
    {
        public string SerializedTypeName { get; set; }
        public byte[] Payload { get; set; }
        public string AuthorRole { get; set; }
        public string RequiredRole { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class RoleBasedSerializer : ISecureSerializer
    {
        private static readonly HashSet<string> AdminTypes = new()
        {
            "SecureApi.Models.UserManagement",
            "SecureApi.Models.SystemConfig",
            "SecureApi.Models.AuditOverride"
        };

        private static readonly HashSet<string> PrivilegedTypes = new()
        {
            "SecureApi.Models.ReportData",
            "SecureApi.Models.BulkExport"
        };

        private readonly ConnectionPool _pool;

        public RoleBasedSerializer(ConnectionPool pool)
        {
            _pool = pool;
        }

        public byte[] Serialize(object data, PooledConnection connection)
        {
            var typeName = data.GetType().FullName;
            var userRole = GetHighestRole(connection.AuthenticatedUser);
            var requiredRole = DetermineRequiredRole(typeName);

            if (!IsAuthorized(userRole, requiredRole))
                throw new UnauthorizedAccessException(
                    $"Role '{userRole}' cannot serialize type '{typeName}'");

            var envelope = new SecureEnvelope
            {
                SerializedTypeName = typeName,
                Payload = SerializeObject(data),
                AuthorRole = userRole,
                RequiredRole = requiredRole,
                Timestamp = DateTime.UtcNow
            };

            return SerializeObject(envelope);
        }

        public T Deserialize<T>(byte[] payload, PooledConnection connection)
        {
            var envelope = DeserializeObject<SecureEnvelope>(payload);
            if (envelope == null)
                throw new SerializationException("Invalid envelope");

            var userRole = GetHighestRole(connection.AuthenticatedUser);
            var requiredRole = envelope.RequiredRole;

            // Authorization check uses envelope's RequiredRole
            // but validates against connection's current user
            if (!IsAuthorized(userRole, requiredRole))
                throw new UnauthorizedAccessException(
                    $"Role '{userRole}' insufficient for type '{envelope.SerializedTypeName}'");

            return DeserializeObject<T>(envelope.Payload);
        }

        private string DetermineRequiredRole(string typeName)
        {
            if (AdminTypes.Contains(typeName)) return "Admin";
            if (PrivilegedTypes.Contains(typeName)) return "Manager";
            return "User";
        }

        private bool IsAuthorized(string userRole, string requiredRole)
        {
            var hierarchy = new Dictionary<string, int>
            {
                ["Admin"] = 100,
                ["Manager"] = 50,
                ["User"] = 10,
                ["Guest"] = 0
            };

            if (!hierarchy.ContainsKey(userRole)) return false;
            if (!hierarchy.ContainsKey(requiredRole)) return false;

            return hierarchy[userRole] >= hierarchy[requiredRole];
        }

        private string GetHighestRole(ClaimsPrincipal principal)
        {
            if (principal == null) return "Guest";
            var roles = new[] { "Admin", "Manager", "User" };
            foreach (var role in roles)
            {
                if (principal.IsInRole(role)) return role;
            }
            return "Guest";
        }

        private byte[] SerializeObject(object obj)
        {
            using var ms = new MemoryStream();
            var formatter = new BinaryFormatter();
            #pragma warning disable SYSLIB0011
            formatter.Serialize(ms, obj);
            #pragma warning restore SYSLIB0011
            return ms.ToArray();
        }

        private T DeserializeObject<T>(byte[] data)
        {
            using var ms = new MemoryStream(data);
            var formatter = new BinaryFormatter();
            #pragma warning disable SYSLIB0011
            return (T)formatter.Deserialize(ms);
            #pragma warning restore SYSLIB0011
        }
    }

    public class SecureApiEndpoint
    {
        private readonly RoleBasedSerializer _serializer;
        private readonly ConnectionPool _pool;

        public SecureApiEndpoint()
        {
            _pool = new ConnectionPool();
            _serializer = new RoleBasedSerializer(_pool);
        }

        public byte[] HandleSerializeRequest(ClaimsPrincipal user, object data)
        {
            var conn = _pool.Acquire(user);
            try
            {
                return _serializer.Serialize(data, conn);
            }
            finally
            {
                _pool.Release(conn.Id);
            }
        }

        public T HandleDeserializeRequest<T>(ClaimsPrincipal user, byte[] payload,
            Guid? reuseConnectionId = null)
        {
            PooledConnection conn;
            if (reuseConnectionId.HasValue)
            {
                conn = _pool.GetConnection(reuseConnectionId.Value);
                if (conn == null)
                    conn = _pool.Acquire(user);
            }
            else
            {
                conn = _pool.Acquire(user);
            }

            try
            {
                return _serializer.Deserialize<T>(payload, conn);
            }
            finally
            {
                if (!reuseConnectionId.HasValue)
                    _pool.Release(conn.Id);
            }
        }
    }
}
